insert into blog_posts (title,slug,short_description,content,category,author,is_published,display_order,faqs,seo_title,meta_description,published_at) values
('Ayurvedic Treatment for Psoriasis: What Actually Helps','ayurvedic-treatment-for-psoriasis','Psoriasis is more than a skin condition; Ayurveda treats it as a signal of deeper imbalance. Here''s how a structured, root-cause approach works.','Psoriasis often arrives as more than a skin concern. The redness, scaling, and itching are visible, but Ayurveda treats them as the surface expression of a deeper imbalance, usually involving digestion, blood tissue (Rakta Dhatu), and immune response.
