insert into faqs (question,answer,category,is_published,display_order) values
('What is Kayachikitsa?','Kayachikitsa is the branch of Ayurveda focused on general internal medicine, the diagnosis and management of diseases affecting the body as a whole. Dr. Pratibha Y.C. holds an M.D. in Kayachikitsa, giving her specialised training in this area.','General',true,0),
('Do you treat patients alongside their existing allopathic medication?','Yes. Many patients continue their prescribed medication while receiving Ayurvedic care. Please bring your current prescriptions and reports to consultation so the plan can be safely coordinated.','General',true,1),
('Is online consultation as effective as an in-person visit?','For most follow-ups and many initial consultations, online sessions work well. Certain conditions requiring physical examination or procedures like Kshara Sutra will need an in-person clinic visit, which will be advised where relevant.','General',true,2),
('How soon can I get an appointment?','Appointment availability varies by day. Use the Book Consultation button or call the clinic directly for the earliest available slot.','General',true,3),
('What should I bring to my first consultation?','Please bring any previous medical reports, a list of current medications, and a summary of your symptoms and their duration. This helps build an accurate, personalised plan from the first visit.','General',true,4);
